"""Dense dashed fan against independently integrated stroke rectangles.

Reference: SVG dash distances along the complete polyline, butt rectangles
and miter/bevel wedges at the on-dash vertices (limit 4). Their scanline union
is integrated exactly in x, with 512 midpoint samples per pixel in y. The
largest change from 256 to 512 samples is 0.365 of an alpha byte. Geometry,
dash phase and reference coverage are independent of the renderer.
"""
import base64
import zlib

from unitgen import Unit, png


ALPHA = ''
PATH = '<path d="M0 0L64 64L64 63.6L0 0.4L0 0.8L64 63.2L64 62.8L0 1.2L0 1.6L64 62.4L64 62L0 2L0 2.4L64 61.6L64 61.2L0 2.8L0 3.2L64 60.8L64 60.4L0 3.6L0 4L64 60L64 59.6L0 4.4L0 4.8L64 59.2L64 58.8L0 5.2L0 5.6L64 58.4L64 58L0 6L0 6.4L64 57.6L64 57.2L0 6.8L0 7.2L64 56.8L64 56.4L0 7.6L0 8L64 56L64 55.6L0 8.4L0 8.8L64 55.2L64 54.8L0 9.2L0 9.6L64 54.4L64 54L0 10L0 10.4L64 53.6L64 53.2L0 10.8L0 11.2L64 52.8L64 52.4L0 11.6L0 12L64 52L64 51.6L0 12.4L0 12.8L64 51.2L64 50.8L0 13.2L0 13.6L64 50.4L64 50L0 14L0 14.4L64 49.6L64 49.2L0 14.8L0 15.2L64 48.8L64 48.4L0 15.6L0 16L64 48L64 47.6L0 16.4L0 16.8L64 47.2L64 46.8L0 17.2L0 17.6L64 46.4L64 46L0 18L0 18.4L64 45.6L64 45.2L0 18.8L0 19.2L64 44.8L64 44.4L0 19.6L0 20L64 44L64 43.6L0 20.4L0 20.8L64 43.2L64 42.8L0 21.2L0 21.6L64 42.4L64 42L0 22L0 22.4L64 41.6L64 41.2L0 22.8L0 23.2L64 40.8L64 40.4L0 23.6L0 24L64 40L64 39.6L0 24.4L0 24.8L64 39.2L64 38.8L0 25.2L0 25.6L64 38.4L64 38L0 26L0 26.4L64 37.6L64 37.2L0 26.8L0 27.2L64 36.8L64 36.4L0 27.6L0 28L64 36L64 35.6L0 28.4L0 28.8L64 35.2L64 34.8L0 29.2L0 29.6L64 34.4L64 34L0 30L0 30.4L64 33.6L64 33.2L0 30.8L0 31.2L64 32.8L64 32.4L0 31.6L0 32L64 32L64 31.6L0 32.4L0 32.8L64 31.2L64 30.8L0 33.2L0 33.6L64 30.4L64 30L0 34L0 34.4L64 29.6L64 29.2L0 34.8L0 35.2L64 28.8L64 28.4L0 35.6L0 36L64 28L64 27.6L0 36.4L0 36.8L64 27.2L64 26.8L0 37.2L0 37.6L64 26.4L64 26L0 38L0 38.4L64 25.6L64 25.2L0 38.8L0 39.2L64 24.8L64 24.4L0 39.6L0 40L64 24L64 23.6L0 40.4L0 40.8L64 23.2L64 22.8L0 41.2L0 41.6L64 22.4L64 22L0 42L0 42.4L64 21.6L64 21.2L0 42.8L0 43.2L64 20.8L64 20.4L0 43.6L0 44L64 20L64 19.6L0 44.4L0 44.8L64 19.2L64 18.8L0 45.2L0 45.6L64 18.4L64 18L0 46L0 46.4L64 17.6L64 17.2L0 46.8L0 47.2L64 16.8L64 16.4L0 47.6L0 48L64 16L64 15.6L0 48.4L0 48.8L64 15.2L64 14.8L0 49.2L0 49.6L64 14.4L64 14L0 50L0 50.4L64 13.6L64 13.2L0 50.8L0 51.2L64 12.8L64 12.4L0 51.6L0 52L64 12L64 11.6L0 52.4L0 52.8L64 11.2L64 10.8L0 53.2L0 53.6L64 10.4L64 10L0 54L0 54.4L64 9.6L64 9.2L0 54.8L0 55.2L64 8.8L64 8.4L0 55.6L0 56L64 8L64 7.6L0 56.4L0 56.8L64 7.2L64 6.8L0 57.2L0 57.6L64 6.4L64 6L0 58L0 58.4L64 5.6L64 5.2L0 58.8L0 59.2L64 4.8L64 4.4L0 59.6" fill="none" stroke="teal" stroke-width=".3" stroke-dasharray=".1 .1"/>'
alpha = zlib.decompress(base64.b64decode(ALPHA))
assert len(alpha) == 64 * 64
pixels = [[(0, 128 / 255, 128 / 255, alpha[y * 64 + x] / 255)
           for x in range(64)] for y in range(64)]
unit = Unit('raster-fan-scan', 64, 64,
            'A dense dashed straight-line fan retains both dash phase and union area. The independent reference includes butt rectangles and the default miter/bevel joins.', ground=False)
unit.cell('fan', (0, 0, 64, 64), PATH,
          f'<image width="64" height="64" href="{png(pixels)}"/>')
unit.write()
